const STATE = require('STATE')
const statedb = STATE(__filename)
const { sdb, get } = statedb(fallback_module)

const receipt_row = require('receipt_row')
const send_button = require('button') 

module.exports = pay_invoice_confirmation

async function pay_invoice_confirmation(opts = {}, callbacks = {}) {
  const onClose = callbacks.onClose || null
  const onConfirm = callbacks.onConfirm || null
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  const on = {
    style: inject,
    data: ondata,
    icons: iconject,
  }

  let dricons = []

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  shadow.innerHTML = `
    <div class="invoice-card">
      <div class="invoice-header">
        <div class="invoice-title-section">
          <div class="invoice-confirmation">Confirmation</div>
          <div class="invoice-amount">
            <div class="light-icon-small"></div>
            <div class="invoice-value" id="invoice-value">0.0000</div>
          </div>       
        </div>
        <div class="close-icon"></div>
      </div>
      <div class="receipt-rows"></div>
      <div class="send-button"></div>
      <style></style>
    </div>
    `

  const style = shadow.querySelector('style')
  const rows_el = shadow.querySelector('.receipt-rows')
  const send_button_container = shadow.querySelector('.send-button')
  const close_icon = shadow.querySelector('.close-icon')

  const subs = await sdb.watch(onbatch)


  let confirm_button = null
  if (subs.length > 0) {
    confirm_button = await send_button(subs[0])
    send_button_container.replaceWith(confirm_button)
    confirm_button.addEventListener('click', (e) => {
      e.stopPropagation()
      if (onConfirm) onConfirm()
    })
  }

  const row_components = []
  for (let i = 1; i < subs.length; i++) {
    const row = await receipt_row(subs[i]) 
    row_components.push(row)
    rows_el.append(row)
  }

  el.updateInvoiceData = function(decoded) {
    if (!decoded) return
    const amt_msat = decoded.amount_msat || 0
    const amt_btc = (amt_msat / 100000000000).toFixed(8)
    const payee = decoded.payee || decoded.destination || 'Unknown'
    const desc = decoded.description || 'Lightning Invoice'
    const estimatedFeeMsat = Number.isFinite(decoded.estimated_fee_msat) ? decoded.estimated_fee_msat : null
    const estimatedFee = estimatedFeeMsat === null ? 'Estimate unavailable' : formatFee(estimatedFeeMsat)
    const estimatedTotalMsat = decoded.estimated_total_msat || (estimatedFeeMsat === null ? null : amt_msat + estimatedFeeMsat)
    
    const valueEl = shadow.querySelector('.invoice-value')
    if (valueEl) valueEl.textContent = amt_btc + ' BTC'
    const titleEl = shadow.querySelector('.invoice-confirmation')
    if (titleEl) titleEl.textContent = 'Confirmation'
    if (confirm_button) confirm_button.style.display = ''

    const newValues = [
      { label: "Amount", value: amt_btc + " BTC", convert: true },
      { label: "Estimated Fee", value: estimatedFee },
      { label: "Recipient Address", value: payee.substring(0, 15) + "..." },
      { label: "Description", value: desc.substring(0, 20) },
      {
        label: "Estimated Total",
        value: estimatedTotalMsat === null ? amt_btc + " BTC + routing fee" : formatTotal(estimatedTotalMsat),
        icon: "lightning.svg"
      }
    ]

    newValues.forEach((val, idx) => {
      if (row_components[idx] && typeof row_components[idx]._update === 'function') {
        row_components[idx]._update(val)
      }
    })
  }

  // Replaces the estimate with the fee confirmed by the completed payment.
  el.updatePaymentData = function(payment) {
    if (!payment) return
    const amountMsat = payment.amount_msat || 0
    const sentAmountMsat = payment.amount_sent_msat || amountMsat
    const confirmedFeeMsat = Number.isFinite(payment.confirmed_fee_msat)
      ? payment.confirmed_fee_msat
      : Math.max(0, sentAmountMsat - amountMsat)
    const titleEl = shadow.querySelector('.invoice-confirmation')
    if (titleEl) titleEl.textContent = 'Payment Successful'
    if (confirm_button) confirm_button.style.display = 'none'
    if (row_components[1] && typeof row_components[1]._update === 'function') {
      row_components[1]._update({ label: "Confirmed Fee", value: formatFee(confirmedFeeMsat) })
    }
    if (row_components[4] && typeof row_components[4]._update === 'function') {
      row_components[4]._update({
        label: "Total Paid",
        value: formatTotal(amountMsat + confirmedFeeMsat),
        icon: "lightning.svg"
      })
    }
  }

  function formatFee(feeMsat) {
    if (feeMsat === 0) return '0 sats'
    if (feeMsat < 1000) return `${feeMsat} msat (${feeMsat / 1000} sats)`
    return `${Number((feeMsat / 1000).toFixed(3))} sats (${feeMsat} msat)`
  }

  function formatTotal(totalMsat) {
    return `${(totalMsat / 100000000000).toFixed(11)} BTC`
  }


  // close on click
  close_icon.addEventListener('click', () => {
    if (onClose) onClose()
  })

  return el

  function fail(data, type) {
    throw new Error('invalid message', { cause: { data, type } })
  }

  async function onbatch(batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(paths.map(path => drive.get(path).then(file => file.raw)))
      const func = on[type] || fail
      await func(data, type)
    }
  }


  function inject(data) {
    style.textContent = data[0]
  }

  function iconject(data) {
    dricons = data
    const light_icon = shadow.querySelectorAll('.light-icon-small')
    const close_icon = shadow.querySelector('.close-icon')

    light_icon.forEach(el => el.innerHTML = dricons[0])
    close_icon.innerHTML = dricons[1]                  
  }

  async function ondata(data) {

    const {value} = data?.[0] || {}
    const btc_value = value[0].value
    const valueEl = shadow.querySelector('.invoice-value')
    
    valueEl.textContent = btc_value

  }
}


function fallback_module() {
  return {
    api,
    _: {
      'button': { $: '' },
      'receipt_row': { 
        $: '' 
      }
    }
  }

  function api(opts) {
    if (!opts) opts = {}
    if (!opts.value) opts.value = {}
 
    const button = {
      mapping: {
        style: 'style',
        data: 'data',
        icons: 'icons'
      },
      0: {
        label: 'Pay invoice'
      }
    }
    const receipt_row = {
      mapping: {
        style: 'style',
        data: 'data',
        icons: 'icons'
      }
    }
    opts.value.forEach((row, index) => {
      receipt_row[index + 1] = row
    })

    return {
      drive: {
        'icons/': {
          'lightning.svg': { '$ref': 'lightning.svg' },
          'x.svg': { '$ref': 'x.svg' }
        },
        'style/': {
          'pay_invoice_confirmation.css': { '$ref': 'pay_invoice_confirmation.css' }
        },
        'data/': {
          'opts.json': { raw: opts || {} }
        }
      },
      _: { button, receipt_row }
    }
  }
}
